          "Felület-előkészítés: A felület lehet szilárd, száraz és tiszta finom mész-, mészcement vagy cementvakolat, valamint száraz és tiszta betonfelületek, cementesztrich felületek, szálerősítésű cement- és gipszkarton lapok, forgácslapok vagy régi csempeburkolatok. A felületet tisztítsuk meg a gyengén tapadó részektől, portól, olaj-és zsírmaradványoktól és egyéb szennyeződésektől. A ragasztót úgy készítjük el, hogy a zsák tartalmát – a 25 kg illetve 5 kg száraz keveréket – belekeverjük ~6,25 l illetve ~1,25 l vízbe, amíg teljesen homogén, csomómentes anyagot nem kapunk.",
