          "Alkalmazási terület: Megfelel az ivóvíz kinyerésére, tárolására és előkészítésére szolgáló építményekkel szemben támasztott követelményeknek (A Szlovéniában hatályos ivóvízről szóló szabályzat 33. cikke szerint). Garantálja a monolit betonfalak jó minőségű vízszigetelő védelmét a pozitív és a negatív víznyomással szemben (a szigetelő réteg lehet a fal bármelyik oldalán), a beton- vagy blokktéglákból készült falak esetén pedig csak a pozitív víznyomással (a szigetelő réteg a fal „vizes oldalán” helyezkedik el,…",
